#!/usr/bin/env python3
"""
FarmBook icon generator.

Place this file in the ROOT of the Flutter repository, next to pubspec.yaml.
The existing GitHub workflow already runs:
    python3 make_icons.py android/app/src/main/res

No Android folder needs to be committed to GitHub.
"""

from pathlib import Path
import base64
import io
import sys

from PIL import Image, ImageDraw, ImageFilter

# The FarmBook logo artwork is embedded so this script needs no extra asset file.
LOGO_PNG_B64 = """"""


def load_logo():
    data = base64.b64decode(LOGO_PNG_B64)
    return Image.open(io.BytesIO(data)).convert("RGBA")


def make_launcher(logo, size):
    # White background keeps the logo clean on Android launchers while allowing
    # the launcher itself to apply its normal mask/shape.
    out = Image.new("RGBA", (size, size), (255, 255, 255, 255))

    # Rounded white app-icon background.
    radius = int(size * 0.22)
    mask = Image.new("L", (size, size), 0)
    d = ImageDraw.Draw(mask)
    d.rounded_rectangle((0, 0, size - 1, size - 1), radius=radius, fill=255)

    bg = Image.new("RGBA", (size, size), (255, 255, 255, 255))
    out = Image.composite(bg, Image.new("RGBA", (size, size), (255,255,255,0)), mask)

    # Keep generous padding around the FarmBook mark.
    target = int(size * 0.68)
    mark = logo.copy()
    mark.thumbnail((target, target), Image.Resampling.LANCZOS)

    # Center the mark.
    x = (size - mark.width) // 2
    y = (size - mark.height) // 2
    out.alpha_composite(mark, (x, y))
    return out


def make_notification_icon(logo, size=96):
    # Android notification small icons should be a simple white silhouette
    # with transparency, not a full-color launcher image.
    alpha = logo.getchannel("A")
    alpha = alpha.resize((size, size), Image.Resampling.LANCZOS)

    # Tight crop inside the notification drawable.
    bbox = alpha.getbbox()
    if bbox:
        alpha = alpha.crop(bbox)

    pad = int(size * 0.12)
    canvas = Image.new("L", (size, size), 0)
    alpha.thumbnail((size - 2*pad, size - 2*pad), Image.Resampling.LANCZOS)
    x = (size - alpha.width) // 2
    y = (size - alpha.height) // 2
    canvas.paste(alpha, (x, y))

    icon = Image.new("RGBA", (size, size), (255, 255, 255, 0))
    icon.putalpha(canvas)
    return icon


def save_all(res_dir):
    res = Path(res_dir)
    logo = load_logo()

    launcher_sizes = {
        "mipmap-mdpi": 48,
        "mipmap-hdpi": 72,
        "mipmap-xhdpi": 96,
        "mipmap-xxhdpi": 144,
        "mipmap-xxxhdpi": 192,
    }

    for folder, size in launcher_sizes.items():
        d = res / folder
        d.mkdir(parents=True, exist_ok=True)
        icon = make_launcher(logo, size)
        icon.save(d / "ic_launcher.png", optimize=True)
        icon.save(d / "ic_launcher_round.png", optimize=True)

    # The notification Dart code uses @drawable/ic_stat_farmbook.
    drawable = res / "drawable"
    drawable.mkdir(parents=True, exist_ok=True)
    notification = make_notification_icon(logo, 96)
    notification.save(drawable / "ic_stat_farmbook.png", optimize=True)

    # Also provide a 512px master PNG for any future tooling.
    master = res / "farmbook_logo.png"
    make_launcher(logo, 512).save(master, optimize=True)

    print("FarmBook icons generated successfully.")
    print("Launcher: mipmap-*/ic_launcher.png")
    print("Notification: drawable/ic_stat_farmbook.png")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python3 make_icons.py android/app/src/main/res")
    save_all(sys.argv[1])
